// Draws the imagined clinic slides (P1 to P4). All fake. Run with NODE_PATH set to a node_modules that has playwright.
const { chromium } = require("playwright");
const V = "C:/Users/DELL/hackathons/neathack/video/clips/";
const CSS = `body{margin:0;background:#0A0B0C;color:#E8E6E1;font-family:Segoe UI,Arial,sans-serif;width:1920px;height:1080px;display:flex;flex-direction:column}
.tag{padding:22px 56px;background:#14161A;border-bottom:1px solid #2a2d33;font-size:28px;color:#C97A3D;letter-spacing:2px}
.main{flex:1;padding:80px 140px;display:flex;flex-direction:column;justify-content:center;gap:34px}
.foot{padding:18px 56px;font-size:22px;color:#7d838a;border-top:1px solid #2a2d33}
.u{align-self:flex-end;background:#1d2127;border-radius:20px;padding:26px 34px;font-size:40px;max-width:1100px}
.a{background:#14161A;border:1px solid #2a2d33;border-radius:20px;padding:26px 34px;font-size:40px;max-width:1300px;line-height:1.5}
.r{color:#D26A5E}.d{color:#7d838a}.big{font-size:104px;font-weight:700;line-height:1.15}`;
const page = (body) => `<html><head><style>${CSS}</style></head><body><div class="tag">IMAGINE. NOT A REAL CASE.</div><div class="main">${body}</div><div class="foot">Invented example, fake patients, drawn for this video. Not real data and not a real clinic.</div></body></html>`;
const meds = "Patient P-4471 medications: Metformin 500 mg twice daily; Lisinopril 10 mg once daily.";
const S = [
  ["P1_imagine_title.png", `<div class="big">Imagine a clinic assistant.</div><div class="d" style="font-size:46px">It looks up a patient's medications from an ID.</div>`],
  ["P2_imagine_normal_request.png", `<div class="u">Medications for patient P-4471, please.</div><div class="a">${meds}</div>`],
  ["P3_imagine_cutoff_wrong_list.png", `<div class="u">Medications for patient P-4<span class="d"> (request cut off)</span></div><div class="a">Patient P-4471 medications: Metformin 500 mg twice daily; Lisinopril 10 mg once daily.<div class="r" style="font-size:30px;margin-top:14px">This is the PREVIOUS patient's list. Same calm tone. No error. No warning.</div></div>`],
  ["P4_imagine_wrong_medication_reaches_patient.png", `<div class="big">The nurse trusts it,<br>because it sounded sure.</div><div class="big r" style="font-size:70px">The wrong medication reaches the patient.</div>`],
];
(async () => {
  const b = await chromium.launch({ executablePath: "C:/Users/DELL/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe" });
