  await b.close();
})();

// TEST voice from a script file. Usage: node voice.mjs SCRIPT_v3_story.md outdir
// One mp3 + vtt per beat. Retries because the free voice service is flaky. Prints durations and total.
import fs from "fs"; import { execSync, spawnSync } from "child_process";
const [, , script, out] = process.argv;
fs.mkdirSync(out, { recursive: true });
const md = fs.readFileSync(script, "utf8");
const beats = [...md.matchAll(/^## ([A-H])\.[^\n]*\n([\s\S]*?)(?=^## |\Z)/gm)].map(m => ({ id: m[1], text: (m[2].match(/^Voiceover: (.*)$/m) || [])[1] })).filter(b => b.text);
let total = 0; const info = [];
for (const b of beats) {
  const mp3 = `${out}/${b.id}.mp3`, vtt = `${out}/${b.id}.vtt`;
  let ok = false;
  for (let t = 0; t < 8 && !ok; t++) {
    const r = spawnSync("python", ["-m", "edge_tts", "--voice", "en-US-AndrewNeural", "--rate=+6%", "--text", b.text, "--write-media", mp3, "--write-subtitles", vtt], { encoding: "utf8" });
    ok = r.status === 0 && fs.existsSync(mp3) && fs.statSync(mp3).size > 2000;
    if (!ok) { spawnSync("python", ["-c", "import time;time.sleep(4)"]); }
  }
  if (!ok) { console.error("FAILED beat", b.id); process.exit(1); }
  const d = parseFloat(execSync(`ffprobe -v error -show_entries format=duration -of csv=p=0 "${mp3}"`).toString());
  total += d; info.push({ id: b.id, dur: d, words: b.text.split(/\s+/).length, text: b.text });
  console.log(b.id, d.toFixed(1), "s", b.text.split(/\s+/).length, "words");
}
fs.writeFileSync(`${out}/beats.json`, JSON.stringify(info, null, 1));
console.log("TOTAL speech", total.toFixed(1), "s");

// Builds the cut from stills + per-beat voice. Usage: node cut.mjs <voicedir> <beatsmap.json> <outprefix> [LABEL]
// beatsmap: { "A": ["P1.png", ...], ... } files are in ../clips. Outputs <outprefix>_silent.mp4 (no voice), <outprefix>.mp4 (voice) and <outprefix>_captioned.mp4 + .srt
import fs from "fs"; import { execSync } from "child_process";
