// v5 cut: stills AND recorded clips (webm), per-beat voice, tag overlays, caption bar.
// Usage: node cut5.mjs <voicedir> <map5.json> <outname> [LABEL]
// map item: "file" or { "f": "file", "ss": seconds, "tag": "text", "w": weight }. Files are looked up in v5/clips, then video/clips.
import fs from "fs"; import { execSync } from "child_process";
const [, , vdir, mapf, outp, label] = process.argv;
const root = "C:/Users/DELL/hackathons/neathack/video/"; const V5 = root + "v5/";
const W = V5 + "work_" + outp + "/"; fs.mkdirSync(W, { recursive: true });
fs.copyFileSync("C:/Windows/Fonts/arial.ttf", V5 + "arial.ttf");
const beats = JSON.parse(fs.readFileSync(vdir + "/beats.json", "utf8")); const map = JSON.parse(fs.readFileSync(mapf, "utf8"));
const GAP = 0.6; const sh = (c) => execSync(c, { stdio: ["ignore", "pipe", "pipe"], cwd: V5 }).toString();
const find = (f) => fs.existsSync(V5 + "clips/" + f) ? "clips/" + f : "../clips/" + f;
const ts = (t) => { const h = Math.floor(t / 3600), m = Math.floor(t % 3600 / 60), s = t % 60; return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${s.toFixed(3).padStart(6, "0").replace(".", ",")}`; };
const parse = (f) => { const t = fs.readFileSync(f, "utf8").replace(/\r/g, ""); const c = []; for (const blk of t.split(/\n\n+/)) { const m = blk.match(/(\d+):(\d+):([\d,.]+) --> (\d+):(\d+):([\d,.]+)\n([\s\S]+)/); if (m) c.push({ s: +m[1] * 3600 + +m[2] * 60 + +m[3].replace(",", "."), e: +m[4] * 3600 + +m[5] * 60 + +m[6].replace(",", "."), t: m[7].replace(/\n/g, " ").trim() }); } return c; };
const dt = (txt, i) => { fs.writeFileSync(W + `tag${i}.txt`, txt); return `,drawtext=fontfile=arial.ttf:textfile=${"work_" + outp}/tag${i}.txt:fontsize=26:fontcolor=0x0A0B0C:box=1:boxcolor=0xC97A3D@0.95:boxborderw=10:x=24:y=h-70`; };
const caps = []; let off = 0, list = "", slist = "", srt = "", n = 0, tg = 0;
for (const b of beats) {
  const items = map[b.id].map((x) => typeof x === "string" ? { f: x } : x); const dur = b.dur + GAP;
  const totalW = items.reduce((a, x) => a + (x.w || 1), 0); const parts = [];
  items.forEach((it, i) => {
    const d = dur * (it.w || 1) / totalW; const fr = Math.round(d * 25); const out = `${W}${b.id}${i}.mp4`; const src = find(it.f); const tag = it.tag ? dt(it.tag, ++tg) : "";
    const vid = /\.webm$/.test(it.f);
    const base = "scale=1280:720:force_original_aspect_ratio=decrease,pad=1280:720:(ow-iw)/2:(oh-ih)/2:color=0x0A0B0C";
    if (vid) {
      let ss = it.ss; if (ss === undefined) { const sf = V5 + src.replace("clips/", "clips/").replace(/\.webm$/, ".start"); ss = fs.existsSync(sf) ? +fs.readFileSync(sf, "utf8") : 0; }
      sh(`ffmpeg -y -loglevel error -ss ${ss} -i ${src} -vf "${base},fps=25,tpad=stop_mode=clone:stop_duration=30,format=yuv420p${tag}" -t ${d.toFixed(3)} -an -c:v libx264 -preset veryfast ${out}`);
    } else {
      sh(`ffmpeg -y -loglevel error -loop 1 -i ${src} -vf "scale=1920:1080:force_original_aspect_ratio=decrease,pad=1920:1080:(ow-iw)/2:(oh-ih)/2:color=0x0A0B0C,zoompan=z='min(zoom+0.0005,1.10)':d=${fr}:s=1280x720:fps=25,format=yuv420p${tag}" -frames:v ${fr} -c:v libx264 -preset veryfast ${out}`);
    }
    parts.push(out);
  });
  fs.writeFileSync(`${W}${b.id}.txt`, parts.map((p) => `file '${p}'`).join("\n"));
  sh(`ffmpeg -y -loglevel error -f concat -safe 0 -i ${W}${b.id}.txt -c copy ${W}${b.id}_v.mp4`);
  sh(`ffmpeg -y -loglevel error -i ${W}${b.id}_v.mp4 -i ${vdir}/${b.id}.mp3 -filter_complex "[1:a]aresample=44100,apad=pad_dur=${GAP}[a]" -map 0:v -map "[a]" -t ${dur} -c:v copy -c:a aac -ar 44100 -ac 1 ${W}${b.id}.mp4`);
  list += `file '${W}${b.id}.mp4'\n`;
  for (const c of parse(`${vdir}/${b.id}.vtt`)) { n++; caps.push({ s: off + c.s, e: off + c.e, t: c.t }); srt += `${n}\n${ts(off + c.s)} --> ${ts(off + c.e)}\n${c.t}\n\n`; }
  off += dur;
}
fs.writeFileSync(W + "list.txt", list);
sh(`ffmpeg -y -loglevel error -f concat -safe 0 -i ${W}list.txt -c copy ${outp}.mp4`); fs.writeFileSync(V5 + outp + ".srt", srt);
const wrap = (t) => { const w = t.split(" "); let L = [""]; for (const x of w) { if ((L[L.length - 1] + " " + x).trim().length > 64) L.push(x); else L[L.length - 1] = (L[L.length - 1] + " " + x).trim(); } return L.join(String.fromCharCode(10)); };
let vf = "pad=1280:810:0:0:color=0x0A0B0C";
caps.forEach((c, i) => { fs.writeFileSync(W + "cap" + i + ".txt", wrap(c.t)); vf += ",drawtext=fontfile=arial.ttf:textfile=work_" + outp + "/cap" + i + ".txt:fontsize=26:fontcolor=0xE6E8E6:x=(w-text_w)/2:y=738:line_spacing=6:enable='between(t," + c.s.toFixed(2) + "," + (c.e + 0.05).toFixed(2) + ")'"; });
if (label) vf += ",drawtext=fontfile=arial.ttf:text='" + label + "':x=12:y=782:fontsize=18:fontcolor=0xC97A3D:box=1:boxcolor=0x0A0B0C@0.8:boxborderw=6";
fs.writeFileSync(W + "vf.txt", vf);
sh(`ffmpeg -y -loglevel error -i ${outp}.mp4 -/vf work_${outp}/vf.txt -c:v libx264 -preset veryfast -c:a copy ${outp}_captioned.mp4`);
console.log("total", off.toFixed(1), "s");
